// Decodifica JWT y valida el body
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || input;

// JWT → clinic_id
const authHeader = (headers.authorization || headers.Authorization || '').toString();
const token = authHeader.replace(/^Bearer\s+/i, '').trim();
if (!token) throw new Error('Authorization token requerido');
const parts = token.split('.');
if (parts.length !== 3) throw new Error('Formato de token inválido');

let clinicId;
try {
  const base64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');
  const padding = '='.repeat((4 - base64.length % 4) % 4);
  const payload = JSON.parse(Buffer.from(base64 + padding, 'base64').toString('utf8'));
  clinicId = payload.clinic_id || payload.clinicId || payload.clinic;
  if (!clinicId) throw new Error('clinic_id no encontrado en el token');
} catch (e) {
  throw new Error('Error al decodificar token: ' + e.message);
}

// Validar campos requeridos
const requiredFields = ['licenseId', 'subscriptionType', 'startDate', 'endDate'];
for (const field of requiredFields) {
  if (!body[field]) throw new Error(`El campo ${field} es requerido`);
}

const VALID_TYPES = ['monthly', 'annual', 'custom'];
if (!VALID_TYPES.includes(body.subscriptionType)) {
  throw new Error(`subscriptionType inválido. Valores permitidos: ${VALID_TYPES.join(', ')}`);
}

const VALID_AI = ['full', 'doctors_only', 'none'];
const aiAccess = body.aiAccess || 'none';
if (!VALID_AI.includes(aiAccess)) {
  throw new Error(`aiAccess inválido. Valores permitidos: ${VALID_AI.join(', ')}`);
}

return [{ json: {
  clinic_id:                String(clinicId),
  license_id:               String(body.licenseId),
  subscription_type:        String(body.subscriptionType),
  start_date:               String(body.startDate),
  end_date:                 String(body.endDate),
  max_doctors:              Number(body.maxDoctors)              || 0,
  max_receptionists:        Number(body.maxReceptionists)        || 0,
  max_admins:               Number(body.maxAdmins)               || 0,
  max_super_admins:         Number(body.maxSuperAdmins)          || 0,
  max_monthly_new_patients: Number(body.maxMonthlyNewPatients)   || 0,
  ai_access:                aiAccess,
  notes:                    body.notes ? String(body.notes) : null,
  issued_at:                body.issuedAt ? String(body.issuedAt) : new Date().toISOString()
} }];

const result = $input.first().json;

if (result.error) {
  throw new Error('Error al crear suscripción: ' + (result.error?.message || String(result.error)));
}
if (!result.id) {
  throw new Error('No se pudo crear la suscripción');
}

return [{ json: result }];
